// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract WrongToken {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Not Nu Token"));
    }
    function callAirDrop(address c) external {
        (bool ok, ) = c.call(abi.encodeWithSignature("airDrop()"));
        ok;
    }
}

contract InvMutTest is Test {
    ModifierEntrancy c;

    function setUp() public {
        c = new ModifierEntrancy();
    }

    function testFuzz_property(uint256 amount) public {
        amount;
        WrongToken wt = new WrongToken();
        bool ok = true;
        try wt.callAirDrop(address(c)) {} catch { ok = false; }
        assertTrue(c.tokenBalance(address(wt)) == 0);
    }
}
